// Percorre todos os itens que chegaram no node
return $input.all().map(item => {
  // Pega a string que está dentro de "output"
  const jsonString = item.json.output;

  // Transforma o texto em um Objeto JSON real
  const objetoLimpo = JSON.parse(jsonString);

  // Retorna o objeto limpo como o novo item
  return {
    json: objetoLimpo
  };
});

const leads = $input.all().map(item => {
    const raw = item.json;
    // Extração Real do Telefone a partir do ID ou Remote JID
    const phoneMatch = (raw.id || raw.remote_jid || "").match(/\d+/);
    const cleanPhone = phoneMatch ? phoneMatch[0] : (raw.telefone || "");

    return {
        ...raw,
        telefone_limpo: cleanPhone,
        valor_num: parseFloat(raw.valor_medio_conta_luz) || 0,
        consumo_num: parseInt(raw.consumo_mensal_kwh) || 0
    };
});

const jsonData = JSON.stringify(leads).replace(/</g, '\\u003c');

let html = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
    <meta charset="UTF-8">
    <title>Promova Solar - Ultra Intelligence CRM</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&family=Plus+Jakarta+Sans:wght@300;400;600;800&display=swap');
        :root { --primary: #3b82f6; --bg: #020617; --surface: #0f172a; --border: #1e293b; }
        body { font-family: 'Plus Jakarta Sans', sans-serif; background: var(--bg); color: #f1f5f9; overflow: hidden; }
        .sidebar { width: 380px; background: rgba(15, 23, 42, 0.95); border-right: 1px solid var(--border); backdrop-filter: blur(20px); }
        .main-view { flex: 1; display: flex; flex-direction: column; height: 100vh; }
        .glass-card { background: rgba(30, 41, 59, 0.5); border: 1px solid var(--border); border-radius: 24px; }
        .data-table-container { flex: 1; overflow: auto; padding: 0 40px 40px 40px; }
        table { width: 100%; border-collapse: separate; border-spacing: 0 8px; }
        th { padding: 16px; text-align: left; font-size: 10px; font-weight: 800; color: #64748b; text-transform: uppercase; letter-spacing: 1px; sticky top: 0; background: var(--bg); z-index: 20; cursor: pointer; }
        th:hover { color: var(--primary); }
        td { padding: 12px 16px; background: var(--surface); font-size: 13px; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
        td:first-child { border-left: 1px solid var(--border); border-top-left-radius: 12px; border-bottom-left-radius: 12px; }
        td:last-child { border-right: 1px solid var(--border); border-top-right-radius: 12px; border-bottom-right-radius: 12px; }
        .badge { padding: 4px 10px; border-radius: 8px; font-size: 10px; font-weight: 800; }
        .critical-glow { box-shadow: 0 0 15px rgba(239, 68, 68, 0.2); border-left: 4px solid #ef4444 !important; }
        .drawer { position: fixed; right: 0; top: 0; width: 650px; height: 100%; background: #0b0f1a; border-left: 1px solid var(--border); transform: translateX(100%); transition: 0.5s cubic-bezier(0.4, 0, 0.2, 1); z-index: 1000; box-shadow: -20px 0 60px rgba(0,0,0,0.8); }
        .drawer.active { transform: translateX(0); }
        .custom-scroll::-webkit-scrollbar { width: 4px; height: 4px; }
        .custom-scroll::-webkit-scrollbar-thumb { background: #334155; border-radius: 10px; }
        input, select { background: #020617 !important; border: 1px solid #1e293b !important; color: white !important; }
    </style>
</head>
<body class="flex h-screen">

    <aside class="sidebar flex flex-col z-50">
        <div class="p-10 border-b border-slate-800">
            <div class="flex items-center gap-4">
                <div class="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center font-black text-xl shadow-blue-500/30 shadow-2xl">P</div>
                <div><h1 class="font-black text-2xl tracking-tighter uppercase leading-none">Promova<span class="text-blue-500">Solar</span></h1><p class="text-[9px] font-bold text-slate-500 tracking-[0.2em] mt-1">INDUSTRIAL CRM</p></div>
            </div>
        </div>

        <div class="flex-1 overflow-y-auto custom-scroll p-8 space-y-8">
            <section>
                <label class="text-[10px] font-black text-slate-500 uppercase tracking-widest">Busca de Inteligência</label>
                <input type="text" id="uiSearch" oninput="engine()" placeholder="Nome, Telefone, Cidade ou ID..." class="w-full mt-2 rounded-xl p-4 text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all">
            </section>

            <section class="grid grid-cols-2 gap-4">
                <div class="col-span-2"><label class="text-[10px] font-black text-slate-500 uppercase">Status de Interesse</label><select id="uiInt" onchange="engine()" class="w-full mt-2 p-3 text-xs rounded-xl"><option value="all">Todos os Níveis</option><option value="alto">Alto Interesse</option><option value="medio">Médio Interesse</option><option value="baixo">Baixo Interesse</option></select></div>
                <div><label class="text-[10px] font-black text-slate-500 uppercase">Telhado</label><select id="uiTel" onchange="engine()" class="w-full mt-2 p-3 text-xs rounded-xl"><option value="all">Todos</option><option value="cerâmica">Cerâmica</option><option value="metálico">Metálico</option><option value="laje">Laje</option><option value="solo">Solo</option></select></div>
                <div><label class="text-[10px] font-black text-slate-500 uppercase">Sentimento</label><select id="uiSen" onchange="engine()" class="w-full mt-2 p-3 text-xs rounded-xl"><option value="all">Todos</option><option value="positivo">Positivo</option><option value="neutro">Neutro</option><option value="negativo">Negativo</option></select></div>
                <div><label class="text-[10px] font-black text-slate-500 uppercase">Etapa</label><select id="uiEta" onchange="engine()" class="w-full mt-2 p-3 text-xs rounded-xl"><option value="all">Todas</option><option value="inicio">Início</option><option value="qualificação">Qualificação</option><option value="reuniao">Reunião</option></select></div>
                <div><label class="text-[10px] font-black text-slate-500 uppercase">Canal</label><select id="uiCan" onchange="engine()" class="w-full mt-2 p-3 text-xs rounded-xl"><option value="all">Todos</option><option value="instagram">Instagram</option><option value="google">Google</option><option value="indicação">Indicação</option></select></div>
            </section>

            <section class="pt-6 border-t border-slate-800 space-y-4">
                <div class="flex justify-between items-center bg-red-500/5 p-4 rounded-2xl border border-red-500/10"><span class="text-xs font-black text-red-500 uppercase">Suporte Crítico</span><input type="checkbox" id="uiSup" onchange="engine()" class="w-5 h-5 accent-red-500"></div>
                <div class="flex justify-between items-center bg-blue-500/5 p-4 rounded-2xl border border-blue-500/10"><span class="text-xs font-black text-blue-500 uppercase">Reunião Ok</span><input type="checkbox" id="uiReu" onchange="engine()" class="w-5 h-5 accent-blue-500"></div>
                <div class="flex justify-between items-center bg-emerald-500/5 p-4 rounded-2xl border border-emerald-500/10"><span class="text-xs font-black text-emerald-500 uppercase">Já Instalou</span><input type="checkbox" id="uiIns" onchange="engine()" class="w-5 h-5 accent-emerald-500"></div>
            </section>
        </div>

        <div class="p-8 border-t border-slate-800"><button onclick="exportCSV()" class="w-full py-4 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-lg shadow-blue-600/20">Gerar Relatório CSV</button></div>
    </aside>

    <main class="main-view">
        <header class="h-28 bg-[#020617]/80 backdrop-blur-md px-12 flex items-center justify-between border-b border-slate-800 shadow-2xl z-20">
            <div class="flex gap-12" id="kpiArea"></div>
            <div class="flex gap-4">
                <button onclick="setView('table')" id="btnTable" class="px-8 py-3 bg-blue-600 rounded-full text-[10px] font-black uppercase tracking-widest">Tabela Densa</button>
                <button onclick="setView('charts')" id="btnCharts" class="px-8 py-3 bg-slate-800 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-500">Analytics</button>
            </div>
        </header>

        <div id="viewCharts" class="hidden flex-1 overflow-y-auto p-12 custom-scroll grid grid-cols-2 gap-8">
            <div class="glass-card p-10"><h3 class="text-xs font-black text-slate-500 uppercase mb-8">Saúde do Funil (Interesse)</h3><canvas id="cInterest"></canvas></div>
            <div class="glass-card p-10"><h3 class="text-xs font-black text-slate-500 uppercase mb-8">Oportunidades por Telhado</h3><canvas id="cRoof"></canvas></div>
            <div class="glass-card p-10 col-span-2"><h3 class="text-xs font-black text-slate-500 uppercase mb-8">Densidade Regional (Cidades)</h3><canvas id="cCity" height="100"></canvas></div>
        </div>

        <div id="viewTable" class="data-table-container custom-scroll pt-10">
            <table>
                <thead>
                    <tr>
                        <th onclick="setSort('nome_real')">Cliente ↕</th>
                        <th onclick="setSort('telefone_limpo')">WhatsApp ↕</th>
                        <th onclick="setSort('cidade_estado')">Localidade ↕</th>
                        <th onclick="setSort('nivel_interesse_compra')">Interesse ↕</th>
                        <th onclick="setSort('valor_num')">Conta Luz ↕</th>
                        <th onclick="setSort('consumo_num')">Consumo ↕</th>
                        <th onclick="setSort('etapa_atendimento')">Etapa ↕</th>
                        <th onclick="setSort('sentimento_conversa')">Sentimento ↕</th>
                        <th class="text-right">Ação</th>
                    </tr>
                </thead>
                <tbody id="mainBody"></tbody>
            </table>
            <div id="noData" class="hidden p-24 text-center text-slate-600 font-black uppercase text-2xl opacity-20">Nenhum registro encontrado</div>
        </div>
    </main>

    <div id="drawer" class="fixed inset-0 bg-black/90 z-[100] hidden justify-end">
        <div id="drawerPanel" class="drawer">
            <div class="p-12 h-full flex flex-col">
                <div class="flex justify-between items-center mb-12">
                    <h2 class="text-3xl font-black italic">DADOS DO PROJETO</h2>
                    <button onclick="closeDrawer()" class="text-5xl font-light opacity-20 hover:opacity-100">&times;</button>
                </div>
                <div id="drawerBody" class="flex-1 space-y-6 overflow-y-auto custom-scroll pr-4"></div>
                <div class="mt-10 pt-10 border-t border-slate-800 flex gap-4">
                    <button id="waBtn" class="flex-1 py-5 bg-emerald-600 hover:bg-emerald-500 rounded-2xl font-black uppercase text-xs tracking-widest transition-all">WhatsApp Direto</button>
                    <button onclick="closeDrawer()" class="px-10 py-5 border border-slate-700 rounded-2xl font-black uppercase text-xs hover:bg-slate-800">Fechar</button>
                </div>
            </div>
        </div>
    </div>

    <script>
        const data = ${jsonData};
        let filtered = [...data];
        let sortK = 'id', sortD = 'desc';
        let charts = { interest: null, roof: null, city: null };

        function engine() {
            const s = document.getElementById('uiSearch').value.toLowerCase();
            const i = document.getElementById('uiInt').value;
            const t = document.getElementById('uiTel').value;
            const n = document.getElementById('uiSen').value;
            const e = document.getElementById('uiEta').value;
            const c = document.getElementById('uiCan').value;
            const sup = document.getElementById('uiSup').checked;
            const reu = document.getElementById('uiReu').checked;
            const ins = document.getElementById('uiIns').checked;

            filtered = data.filter(d => {
                const searchStr = (d.nome_real + ' ' + d.nome_completo + ' ' + d.telefone_limpo + ' ' + d.cidade_estado + ' ' + d.id).toLowerCase();
                const mS = searchStr.includes(s);
                const mI = i === 'all' || (d.nivel_interesse_compra||'').toLowerCase().includes(i);
                const mT = t === 'all' || (d.tipo_telhado||'').toLowerCase().includes(t);
                const mN = n === 'all' || (d.sentimento_conversa||'').toLowerCase().includes(n);
                const mE = e === 'all' || (d.etapa_atendimento||'').toLowerCase().includes(e);
                const mC = c === 'all' || (d.canal_aquisicao||'').toLowerCase().includes(c);
                const mSup = !sup || !!d.problema_suporte_relatado;
                const mReu = !reu || !!d.reuniao_confirmada;
                const mIns = !ins || !!d.cliente_ja_instalou;
                return mS && mI && mT && mN && mE && mC && mSup && mReu && mIns;
            });

            sorter(); render(); updateKPIs(); if(!document.getElementById('viewCharts').classList.contains('hidden')) updateCharts();
        }

        function sorter() {
            filtered.sort((a,b) => {
                let vA = a[sortK] || ''; let vB = b[sortK] || '';
                if(typeof vA === 'string') { vA = vA.toLowerCase(); vB = vB.toLowerCase(); }
                return sortD === 'asc' ? (vA > vB ? 1 : -1) : (vA < vB ? 1 : -1);
            });
        }

        function setSort(k) { if(sortK === k) sortD = sortD === 'asc' ? 'desc' : 'asc'; else { sortK = k; sortD = 'asc'; } engine(); }

        function render() {
            const body = document.getElementById('mainBody'); body.innerHTML = '';
            document.getElementById('noData').classList.toggle('hidden', filtered.length > 0);
            filtered.forEach(d => {
                const tr = document.createElement('tr');
                tr.className = 'data-row ' + (d.problema_suporte_relatado ? 'critical-glow' : '');
                const intClass = (d.nivel_interesse_compra||'').toLowerCase().includes('alto') ? 'bg-emerald-500/10 text-emerald-400' : 'bg-slate-800 text-slate-400';
                const sentColor = (d.sentimento_conversa||'').toLowerCase() === 'positivo' ? 'text-emerald-400' : (d.sentimento_conversa||'').toLowerCase() === 'negativo' ? 'text-rose-400' : 'text-slate-400';

                tr.innerHTML = \`<td class='p-6'><div class='font-bold text-white'>\${d.nome_real || d.nome_completo || 'N/A'}</div><div class='text-[9px] font-mono text-slate-500 uppercase mt-1'>ID: \${d.id}</div></td>\` +
                               \`<td class='p-6 font-mono text-blue-400'>\${d.telefone_limpo || '-'}</td>\` +
                               \`<td class='p-6 text-slate-400'>\${d.cidade_estado || '-'}</td>\` +
                               \`<td class='p-6'><span class='badge \${intClass}'>\${d.nivel_interesse_compra || 'N/A'}</span></td>\` +
                               \`<td class='p-6 font-bold text-emerald-400'>R$ \${parseFloat(d.valor_medio_conta_luz||0).toFixed(2)}</td>\` +
                               \`<td class='p-6 font-bold'>\${d.consumo_mensal_kwh || 0} kWh</td>\` +
                               \`<td class='p-6 font-bold text-blue-500 uppercase text-[10px]'>\${d.etapa_atendimento || '-'}</td>\` +
                               \`<td class='p-6 font-bold \${sentColor} uppercase text-[10px]'>\${d.sentimento_conversa || '-'}</td>\` +
                               \`<td class='p-6 text-right'><button onclick='openDrawer("\${d.id}")' class='px-5 py-2 bg-slate-800 rounded-xl font-black text-[9px] hover:bg-blue-600 transition-all'>DETALHES</button></td>\`;
                body.appendChild(tr);
            });
        }

        function updateKPIs() {
            const totalVal = filtered.reduce((acc, i) => acc + (parseFloat(i.valor_medio_conta_luz)||0), 0);
            const ticket = totalVal / (filtered.length || 1);
            const kpi = document.getElementById('kpiArea');
            const box = (l, v, c) => \`<div><p class='text-[10px] font-black text-slate-500 uppercase tracking-widest'>\${l}</p><h3 class='text-2xl font-black \${c} mt-1'>\${v}</h3></div>\`;
            kpi.innerHTML = box('Leads', filtered.length, 'text-white') + box('Ticket Médio', 'R$ ' + ticket.toFixed(0), 'text-blue-500') + box('Potencial Total', 'R$ ' + totalVal.toLocaleString(), 'text-emerald-400');
        }

        function openDrawer(id) {
            const d = data.find(x => x.id === id); if(!d) return;
            const b = document.getElementById('drawerBody');
            const item = (l, v) => \`<div class='p-5 bg-slate-900 rounded-2xl border border-slate-800'><label class='text-[9px] font-black text-blue-500 uppercase block mb-1 tracking-tighter'>\${l}</label><div class='text-sm font-bold text-slate-200'>\${v || 'Não Informado'}</div></div>\`;
            b.innerHTML = \`<div class='grid grid-cols-2 gap-4'>\` +
                item('Nome Real', d.nome_real) + item('Telefone Original', d.telefone) +
                item('Cidade / Estado', d.cidade_estado) + item('Email', d.email) +
                item('Valor Conta Luz', 'R$ ' + d.valor_medio_conta_luz) + item('Consumo Mensal', d.consumo_mensal_kwh + ' kWh') +
                item('Telhado / Fase', d.tipo_telhado + ' / ' + d.fase_da_rede) + item('Concessionária', d.concessionaria_energia) +
                \`<div class='col-span-2 text-[10px] font-black text-slate-500 uppercase mt-4 mb-2'>Inteligência & Atendimento</div>\` +
                item('Sentimento', d.sentimento_conversa) + item('Etapa Atual', d.etapa_atendimento) +
                item('Forma de Pgto', d.forma_pagamento_desejada) + item('Financiamento', d.status_financiamento) +
                \`<div class='col-span-2'>\` + item('Histórico Relevante', d.historico_infos_relevantes) + \`</div>\` +
                \`<div class='col-span-2'>\` + item('Objeções', d.objecoes) + \`</div>\` +
                \`<div class='col-span-2 border-l-4 border-rose-500'>\` + item('Problema Suporte', d.problema_suporte_relatado) + \`</div></div>\`;

            document.getElementById('waBtn').onclick = () => window.open(\`https://wa.me/\${d.telefone_limpo}\`);
            document.getElementById('drawer').classList.replace('hidden', 'flex');
            setTimeout(() => document.getElementById('drawerPanel').classList.add('active'), 10);
        }

        function closeDrawer() { document.getElementById('drawerPanel').classList.remove('active'); setTimeout(() => document.getElementById('drawer').classList.replace('flex', 'hidden'), 400); }

        function setView(v) {
            document.getElementById('viewTable').classList.toggle('hidden', v === 'charts');
            document.getElementById('viewCharts').classList.toggle('hidden', v === 'table');
            document.getElementById('btnTable').className = v === 'table' ? 'px-8 py-3 bg-blue-600 rounded-full text-[10px] font-black uppercase tracking-widest' : 'px-8 py-3 bg-slate-800 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-500';
            document.getElementById('btnCharts').className = v === 'charts' ? 'px-8 py-3 bg-blue-600 rounded-full text-[10px] font-black uppercase tracking-widest' : 'px-8 py-3 bg-slate-800 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-500';
            if(v === 'charts') initCharts();
        }

        function initCharts() {
            const ctxI = document.getElementById('cInterest').getContext('2d');
            const ctxR = document.getElementById('cRoof').getContext('2d');
            const ctxC = document.getElementById('cCity').getContext('2d');
            Chart.defaults.color = '#64748b'; Chart.defaults.font.family = 'Plus Jakarta Sans';

            charts.interest = new Chart(ctxI, { type: 'doughnut', data: { labels: ['Alto', 'Outros'], datasets: [{ data: [0, 0], backgroundColor: ['#10b981', '#1e293b'], borderWidth: 0 }] }, options: { cutout: '85%' } });
            charts.roof = new Chart(ctxR, { type: 'bar', data: { labels: [], datasets: [{ data: [], backgroundColor: '#3b82f6', borderRadius: 8 }] }, options: { plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true, grid: { color: '#1e293b' } } } } });
            charts.city = new Chart(ctxC, { type: 'line', data: { labels: [], datasets: [{ data: [], borderColor: '#3b82f6', tension: 0.4, fill: true, backgroundColor: 'rgba(59, 130, 246, 0.1)' }] }, options: { plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true, grid: { color: '#1e293b' } } } } });
            updateCharts();
        }

        function updateCharts() {
            const alto = filtered.filter(x => (x.nivel_interesse_compra||'').toLowerCase().includes('alto')).length;
            charts.interest.data.datasets[0].data = [alto, filtered.length - alto]; charts.interest.update();

            const roofs = {}; filtered.forEach(x => { const r = x.tipo_telhado || 'N/D'; roofs[r] = (roofs[r] || 0) + 1; });
            charts.roof.data.labels = Object.keys(roofs); charts.roof.data.datasets[0].data = Object.values(roofs); charts.roof.update();

            const cities = {}; filtered.forEach(x => { const c = x.cidade_estado || 'N/D'; cities[c] = (cities[c] || 0) + 1; });
            const sortedCities = Object.entries(cities).sort((a,b) => b[1] - a[1]).slice(0, 10);
            charts.city.data.labels = sortedCities.map(x => x[0]); charts.city.data.datasets[0].data = sortedCities.map(x => x[1]); charts.city.update();
        }

        function exportCSV() {
            let csv = 'ID;Nome;Telefone;Cidade;Interesse;Valor;Consumo;Etapa;Sentimento\\n';
            filtered.forEach(r => { csv += \`\${r.id};\${r.nome_real};\${r.telefone_limpo};\${r.cidade_estado};\${r.nivel_interesse_compra};\${r.valor_medio_conta_luz};\${r.consumo_mensal_kwh};\${r.etapa_atendimento};\${r.sentimento_conversa}\\n\`; });
            const blob = new Blob(['\\ufeff' + csv], { type: 'text/csv' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'crm_promova.csv'; a.click();
        }

        window.onload = () => engine();
    </script>
</body>
</html>
`;

return [{ json: { html_final: html } }];
